// Generated by Cypress Author on 2026-10-11.
// Functional tests only: the look of each play is covered by the image snapshots in TrackItem.cy.tsx.
import type { StaticResponse } from 'cypress/types/net-stubbing';
import {
  currentlyPlayingResponse,
  NOW,
  nowPlayingTrack,
  playedTrack,
  playsBeforeTodayResponse,
  recentlyPlayedResponse,
} from '../../cypress/fixtures/recentlyPlayed.ts';
import { stubAlbumCover } from '../../cypress/support/albumCover.ts';
import ListeningHistory from './ListeningHistory.tsx';

const history = '[data-cy="listening-history"]';
const day = '[data-cy="listening-day"]';

/** Asserts the day headings, top to bottom. */
function expectDays(labels: string[]) {
  cy.get(`${day} h3`).then(($headings) => {
    expect([...$headings].map((heading) => heading.textContent)).to.deep.equal(labels);
  });
}

/** Asserts the text of the `$names` elements, top to bottom. */
function expectNames($names: JQuery, names: string[]) {
  expect([...$names].map((name) => name.textContent)).to.deep.equal(names);
}

/** Asserts the track names in the whole history, top to bottom. */
function expectTrackNames(names: string[]) {
  cy.get(`${history} [data-cy="track-name"]`).then(($names) => expectNames($names, names));
}

/** Asserts the track names in Today's section, top to bottom. */
function expectTodayTrackNames(names: string[]) {
  cy.get(day).first().find('[data-cy="track-name"]').then(($names) => expectNames($names, names));
}

describe('<ListeningHistory />', () => {
  beforeEach(() => {
    stubAlbumCover();
    // Fix only `Date`, so "Today" and "Yesterday" are stable while timers and requests keep running.
    cy.clock(NOW, ['Date']);
    // Nothing is playing unless a test says otherwise. Later intercepts override this one.
    cy.intercept('GET', '/api/currently-playing', { body: { nowPlaying: null } }).as('currentlyPlaying');
  });

  describe('when the history loads', () => {
    beforeEach(() => {
      cy.intercept('GET', '/api/recently-played', { body: recentlyPlayedResponse }).as('recentlyPlayed');
    });

    it('nothing playing → one section per day, Today first, without a now-playing track', () => {
      cy.mount(<ListeningHistory />);
      cy.wait(['@recentlyPlayed', '@currentlyPlaying']);

      cy.get(`${history} h2`).should('have.text', 'Your diary');
      expectDays(['Today', 'Yesterday', 'Wednesday, October 7']);
      cy.get(day).eq(0).should('contain.text', '2 tracks');
      cy.get(day).eq(1).should('contain.text', '2 tracks');
      cy.get(day).eq(2).should('contain.text', '1 track');
      cy.get('[data-cy="track-playback"]').should('not.exist');
    });

    it('plays arrive out of order → the most recently played track is at the top', () => {
      cy.mount(<ListeningHistory />);
      cy.wait('@recentlyPlayed');

      expectTrackNames([
        'Paper Lanterns',
        'Morning Coffee',
        'Midnight Train Through the Northern Lights (Extended Orchestral Version)',
        'Commute',
        'Voice Memo Jam',
      ]);
      cy.get(day).eq(0).find('[data-cy="track-item"]').should('have.length', 2);
    });

    // Generated by Cypress Author on 2026-10-11.
    // Spotify adds the playing track to the history only once it ends, so the list adds it to Today itself.
    it('a track is playing → it is at the top of Today, marked "Now playing", and counted', () => {
      cy.intercept('GET', '/api/currently-playing', { body: currentlyPlayingResponse }).as('currentlyPlaying');
      cy.mount(<ListeningHistory />);
      cy.wait(['@recentlyPlayed', '@currentlyPlaying']);

      expectDays(['Today', 'Yesterday', 'Wednesday, October 7']);
      cy.get(day).eq(0).find('[data-cy="listening-day-count"]').should('have.text', '3 tracks');
      expectTodayTrackNames(['Golden Hour Drive', 'Paper Lanterns', 'Morning Coffee']);
      cy.get(day)
        .first()
        .find('[data-cy="track-item"]')
        .first()
        .find('[data-cy="track-playback"]')
        .should('have.text', 'Now playing');
      cy.get('[data-cy="track-playback"]').should('have.length', 1);
      cy.get(day).eq(1).find('[data-cy="listening-day-count"]').should('have.text', '2 tracks');
    });

    // Generated by Cypress Author on 2026-10-11.
    it('the playing track started yesterday → it still goes at the top of Today, not under Yesterday', () => {
      const startedYesterday = { ...nowPlayingTrack, playedAt: new Date(2026, 9, 10, 23, 58).toISOString() };
      cy.intercept('GET', '/api/currently-playing', { body: { nowPlaying: startedYesterday } });
      cy.mount(<ListeningHistory />);

      expectTodayTrackNames(['Golden Hour Drive', 'Paper Lanterns', 'Morning Coffee']);
      cy.get(day)
        .eq(1)
        .should('contain.text', 'Yesterday')
        .find('[data-cy="listening-day-count"]')
        .should('have.text', '2 tracks');
    });

    // Generated by Cypress Author on 2026-10-11.
    // The playing track is extra: when it can't be loaded, the history shows without it and no error appears.
    const failures: [string, StaticResponse][] = [
      ['Spotify fails (502 spotify_error)', { statusCode: 502, body: { error: 'spotify_error', status: 503 } }],
      [
        'playback access missing (403 spotify_scope_missing)',
        { statusCode: 403, body: { error: 'spotify_scope_missing' } },
      ],
      ['a non-JSON error page', { statusCode: 500, headers: { 'content-type': 'text/html' }, body: '<h1>Oops</h1>' }],
      ['a network error', { forceNetworkError: true }],
    ];
    for (const [failure, response] of failures) {
      it(`loading the playing track fails with ${failure} → the history still shows`, () => {
        cy.intercept('GET', '/api/currently-playing', response);
        cy.mount(<ListeningHistory />);

        expectDays(['Today', 'Yesterday', 'Wednesday, October 7']);
        cy.get(day).eq(0).find('[data-cy="listening-day-count"]').should('have.text', '2 tracks');
        cy.get('[data-cy="track-playback"]').should('not.exist');
        cy.get('[role="alert"]').should('not.exist');
      });
    }
  });

  it('a play from last year → its day heading includes the year', () => {
    const newYearsEve = { ...playedTrack, playedAt: new Date(2025, 11, 31, 23, 30).toISOString() };
    cy.intercept('GET', '/api/recently-played', { body: { items: [newYearsEve] } });
    cy.mount(<ListeningHistory />);

    cy.contains(`${day} h3`, 'Wednesday, December 31, 2025').should('be.visible');
  });

  // Generated by Cypress Author on 2026-10-11.
  it('no plays today and nothing playing → Today says nothing was played yet, earlier days follow', () => {
    cy.intercept('GET', '/api/recently-played', { body: playsBeforeTodayResponse });
    cy.mount(<ListeningHistory />);

    expectDays(['Today', 'Yesterday', 'Wednesday, October 7']);
    cy.get(day)
      .eq(0)
      .within(() => {
        cy.get('[data-cy="listening-day-empty"]').should('have.text', 'Nothing played yet today.');
        cy.get('[data-cy="track-item"]').should('not.exist');
        cy.get('[data-cy="listening-day-count"]').should('not.exist');
      });
    cy.get(day).eq(1).find('[data-cy="listening-day-count"]').should('have.text', '2 tracks');
  });

  // Generated by Cypress Author on 2026-10-11.
  it('no plays at all → only Today shows, saying nothing was played yet', () => {
    cy.intercept('GET', '/api/recently-played', { body: { items: [] } });
    cy.mount(<ListeningHistory />);

    expectDays(['Today']);
    cy.get('[data-cy="listening-day-empty"]').should('have.text', 'Nothing played yet today.');
  });

  // Generated by Cypress Author on 2026-10-11.
  it('no plays today but a track is playing → Today shows just that track', () => {
    cy.intercept('GET', '/api/recently-played', { body: playsBeforeTodayResponse });
    cy.intercept('GET', '/api/currently-playing', { body: currentlyPlayingResponse });
    cy.mount(<ListeningHistory />);

    expectTodayTrackNames(['Golden Hour Drive']);
    cy.get(day).eq(0).find('[data-cy="listening-day-count"]').should('have.text', '1 track');
    cy.get('[data-cy="listening-day-empty"]').should('not.exist');
  });

  it('while loading → shows a busy placeholder', () => {
    // Hold the response back so the placeholder stays on screen.
    cy.intercept('GET', '/api/recently-played', { body: recentlyPlayedResponse, delay: 30_000 });
    cy.mount(<ListeningHistory />);

    cy.get(`${history} [aria-busy="true"]`).should('have.attr', 'aria-label', 'Loading your listening history');
  });

  it('Spotify fails → shows a friendly error', () => {
    cy.intercept('GET', '/api/recently-played', { statusCode: 502, body: { error: 'spotify_error' } });
    cy.mount(<ListeningHistory />);

    cy.get('[role="alert"]')
      .should('contain.text', "We couldn't load your listening history")
      .and('contain.text', 'Spotify did not respond');
  });

  // Generated by Cypress Author on 2026-10-11.
  // A 403 has two meanings, so the message follows the `error` code in the body, not the status.
  // The history decides what shows: a playing track doesn't replace its error.
  it('Spotify refuses the history (403 spotify_scope_missing) → suggests reconnecting Spotify to allow access', () => {
    cy.intercept('GET', '/api/recently-played', { statusCode: 403, body: { error: 'spotify_scope_missing' } });
    cy.intercept('GET', '/api/currently-playing', { body: currentlyPlayingResponse });
    cy.mount(<ListeningHistory />);

    cy.get('[role="alert"]')
      .should('contain.text', "We couldn't load your listening history")
      .and('contain.text', "Spotify hasn't shared your listening history yet")
      .and('contain.text', 'Manage account')
      .and('not.contain.text', 'No Spotify account');
    cy.get(day).should('not.exist');
  });

  // Generated by Cypress Author on 2026-10-11.
  it('no Spotify account connected (403 spotify_not_connected) → says no account is connected', () => {
    cy.intercept('GET', '/api/recently-played', { statusCode: 403, body: { error: 'spotify_not_connected' } });
    cy.mount(<ListeningHistory />);

    cy.get('[role="alert"]')
      .should('contain.text', 'No Spotify account is connected to your profile.')
      .and('not.contain.text', "Spotify hasn't shared");
  });

  // Generated by Cypress Author on 2026-10-11.
  it('the server answers with a non-JSON error page → shows a generic error with the status', () => {
    cy.intercept('GET', '/api/recently-played', {
      statusCode: 500,
      headers: { 'content-type': 'text/html' },
      body: '<h1>Internal Server Error</h1>',
    });
    cy.mount(<ListeningHistory />);

    cy.get('[role="alert"]').should('contain.text', 'Request failed with status 500.');
  });

  describe('when Spotify has not shared the listening history', () => {
    beforeEach(() => {
      cy.intercept('GET', '/api/recently-played', { body: recentlyPlayedResponse }).as('recentlyPlayed');
    });

    it('clicking Allow → asks Spotify for access, without requesting the history or the playing track', () => {
      const onAllow = cy.stub().as('onAllow').resolves();
      cy.mount(<ListeningHistory onAllowListeningHistory={onAllow} />);

      cy.get('[data-cy="allow-listening-history"]')
        .should('contain.text', "Allow Spotify Diary to see what you've been listening to.")
        .contains('button', 'Allow')
        .click();

      cy.get('@onAllow').should('have.been.calledOnce');
      cy.get('@recentlyPlayed.all').should('have.length', 0);
      cy.get('@currentlyPlaying.all').should('have.length', 0);
    });

    it('asking Spotify fails → explains the problem so the user can retry', () => {
      cy.mount(<ListeningHistory onAllowListeningHistory={cy.stub().rejects(new Error('network'))} />);

      cy.contains('[data-cy="allow-listening-history"] button', 'Allow').click();

      cy.get('[data-cy="allow-listening-history"]').should('contain.text', "We couldn't reach Spotify. Please try again.");
      cy.contains('[data-cy="allow-listening-history"] button', 'Allow').should('be.enabled');
    });
  });
});
